public class AccountsService {

    private static final String ARREST_RNO = "H_RNO";
    private static final String CURRENCY_CODE_RUR = "RUR";
    private static final String BANKRUPT_ACCOUNT_TYPE_ZO = "ZO";
    private static final String LANGUAGE = "RU";

    private final AccountBaseInfoGateway accountBaseInfoGateway;
    private final AccountListGbaGateway accountListGbaGateway;
    private final CustomerNewAccountTypesGateway customerNewAccountTypesGateway;
    private final CustomerNewAccountRestrictionsGateway customerNewAccountRestrictionsGateway;
    private final AccountNewGateway accountNewGateway;
    private final CodeBusinessEventGateway codeBusinessEventGateway;
    private final OperationTypeConfiguration operationTypeConfiguration;
    private final BranchInfoService branchInfoService;
    private final AccountingEntryService accountingEntryService;
    private final AccountMovementListGateway accountMovementListGateway;
    private final AccountBalanceGateway accountBalanceGateway;
    private final AccountSetMainAccGateway accountSetMainAccGateway;
    private final UWSCardComboAccount10Client uwsCardComboAccount10Client;
    private final AccountNamesGateway accountNamesGateway;
    private final ComboInfoMapper comboInfoMapper;
    private final Logger maskedLog;
    private final CodeAccountTypeInfoGetGateway codeAccountTypeInfoGetGateway;
    private final CodeAddInfValueInfoGetGateway codeAddInfValueInfoGetGateway;
    private final CodeCurrencyInfoGateway codeCurrencyInfoGateway;
    private final CodeResponsibilityListGetGateway codeResponsibilityListGetGateway;
    private final BaseAccountInfoMapper baseAccountInfo;

    @Value("${max_concurrent_requests}")
    private Integer maxConcurrentRequests;

    @Setter
    @Value("#{'${accounts-api.account-types-for-share}'.split(',')}")
    private Set<String> accountTypesForShare;

    boolean filterAccountsPredicate(String pinEq, String[] act,
                                    String[] includeCurrencies, String[] excludeCurrencies,
                                    boolean ignoreAccountingMode, boolean includeAccountsWithSpecificTypes,
                                    Account account) {
        String acceptCondition;
        if (StringUtils.isEmpty(account.getAccountNumber())) {
            acceptCondition = "!StringUtils.isEmpty(account.getAccountNumber()";
        } else if (act != null && !StringUtils.containsAny(account.getAct(), act)) {
            acceptCondition = "StringUtils.containsAny(account.getAct(), act)";
        } else if (isNotEmpty(includeCurrencies) && !StringUtils.containsAny(account.getBaseCurrencyCode(), includeCurrencies)) {
            acceptCondition = "StringUtils.containsAny(account.getBaseCurrencyCode(), includeCurrencies)";
        } else if (isNotEmpty(excludeCurrencies) && StringUtils.containsAny(account.getBaseCurrencyCode(), excludeCurrencies)) {
            acceptCondition = "!StringUtils.containsAny(account.getBaseCurrencyCode(), excludeCurrencies)";
        } else if (pinNotEqualOrIsNotSpecificType(pinEq, includeAccountsWithSpecificTypes, accountTypesForShare, account)) {
            acceptCondition = "!pinEq.equalsIgnoreCase(account.getAccountOwner())";
        } else if (!ignoreAccountingMode && StringUtils.containsAny(account.getAccountingMode(), "400", "500")) {
            acceptCondition = "!StringUtils.containsAny(account.getAccountingMode(), '400', '500')";
        } else {
            acceptCondition = StringUtils.EMPTY;
        }
        maskedLog.info("check account: {} -> {} - {}", account, acceptCondition.isEmpty(), acceptCondition);
        return acceptCondition.isEmpty();
    }

    private boolean pinNotEqualOrIsNotSpecificType(String pinEq,
                                                   boolean includeAccountsWithSpecificTypes,
                                                   Set<String> accountTypesForShare,
                                                   Account account) {
        if (!pinEq.equalsIgnoreCase(account.getAccountOwner())) {
            //  Если параметр includeAccountsWithSpecificTypes = true, и тип счет входит в список accountTypesForShare,
            //  то счет включается в результирующий список. https://jira.moscow.alfaintra.net/browse/RBSCALL-726
            if (includeAccountsWithSpecificTypes && accountTypesForShare.contains(account.getAct())) {
                return false;
            }
            return true;
        }
        return false;
    }

    public Account getAccountByNumber(String accountNumber) {
        return accountBaseInfoGateway.getAccountByNumber(accountNumber);
    }

    public BaseAccountInfo getBaseAccountInfoByNumber(String accountNumber) throws NotFoundException,SystemServiceException {
        Account accountBaseInfo;
        try {
            accountBaseInfo = accountBaseInfoGateway.getAccountByNumber(accountNumber);
        }
        catch (UndeclaredThrowableException e) {
            log.error("getBaseAccountInfoByNumber", e);
            throw new NotFoundException("Account does not exist on the database from AccountBaseInfoGateway.");
        }
        catch (Exception e) {
            log.error("getBaseAccountInfoByNumber", e);
            throw new SystemServiceException("accountBaseInfo","Ошибка при загрузке данных. Попробуйте позже или обратитесь в HelpDesk.");
        }

        AccountTypeInfo accountTypeInfo = codeAccountTypeInfoGetGateway.getAccountTypeInfo(accountBaseInfo.getAct(), LANGUAGE);
        log.info("#getBaseAccountInfoByNumber: accountTypeInfo = {}", accountTypeInfo);
        AddInfValueInfo executorInfo = codeAddInfValueInfoGetGateway
                .getAddInfValueInfoByCode(OperatorType.EXECUTOR, accountBaseInfo.getAccountExCode());
        log.info("#getBaseAccountInfoByNumber: executorInfo = {}", executorInfo);
        AddInfValueInfo managerInfo = codeAddInfValueInfoGetGateway
                .getAddInfValueInfoByCode(OperatorType.MANAGER, accountBaseInfo.getAccountMgrCode());
        log.info("#getBaseAccountInfoByNumber: managerInfo = {}", managerInfo);
        CurrencyInfo currencyInfo = codeCurrencyInfoGateway.getCurrencyInfo(accountBaseInfo.getBaseCurrencyCode(), LANGUAGE);
        log.info("#getBaseAccountInfoByNumber: currencyInfo = {}", currencyInfo);
        BranchInfo branchInfo = branchInfoService.getBranchInfo(accountBaseInfo.getBranchId());
        log.info("#getBaseAccountInfoByNumber: branchInfo = {}", branchInfo);
        Responsibility responsibility = codeResponsibilityListGetGateway
                .getResponsibilityInfo(accountBaseInfo.getResponsibleDeptCode(), LANGUAGE);
        log.info("#getBaseAccountInfoByNumber: responsibility = {}", responsibility);
        return baseAccountInfo.toBaseAccountInfo(
                accountBaseInfo,
                accountTypeInfo,
                currencyInfo,
                executorInfo,
                managerInfo,
                branchInfo,
                responsibility
        );
    }

    public Set<Account> getAccountListByParams(String pinEq, String[] act, String[] operationTypes, String[] includeCurrencies,
                                               String[] excludeCurrencies, boolean getBranchInfo, boolean ignoreAccountingMode,
                                               boolean getLastTransactionDate, boolean getBalanceGovernment, boolean useNewBalance,
                                               String[] accountNumbers, boolean includeAccountsWithSpecificTypes, boolean getComboInfo) {
        log.debug("#getAccountListByParams: pinEq={}, act={}, includeCurrencies={}, excludeCurrencies={}, getBranchInfo={}, ignoreAccountingMode={}, getLastTransactionDate={}, getBalanceGovernment={}, useNewBalance={}, accountNumbers={}, getComboInfo={}",
                pinEq, act, includeCurrencies, excludeCurrencies, getBranchInfo, ignoreAccountingMode, getLastTransactionDate, getBalanceGovernment, useNewBalance, accountNumbers, getComboInfo);

        Set<Account> result = Optional.ofNullable(operationTypes)
                .filter(ArrayUtils::isNotEmpty)
                .map(getAccountsByOperationType(pinEq, act, useNewBalance, accountNumbers))
                .orElseGet(() -> accountListGbaGateway.getAccountListByPinEqAndActIn(pinEq, null, act, useNewBalance, accountNumbers).stream())
                .filter(account -> filterAccountsPredicate(pinEq, act, includeCurrencies, excludeCurrencies,
                        ignoreAccountingMode, includeAccountsWithSpecificTypes, account))
                .collect(toCollection(LinkedHashSet::new));
        log.info("#getAccountListByParams: found {} accounts for pinEq {}", result.size(), pinEq);
        if (getBranchInfo) {
            fillBranchInfo(result);
        }
        if (getLastTransactionDate) {
            fillLastTransactionDate(result);
        }
        if (getBalanceGovernment) {
            fillBalanceGovernment(result);
        }
        if (getComboInfo) {
            fillComboInfo(result, pinEq);
        }
        return result;
    }

    private Function<String[], Stream<Account>> getAccountsByOperationType(String pinEq, String[] act, boolean useNewBalance, String[] accountNumbers) {
        return ot -> Stream.of(ot)
                .map(o -> operationTypeConfiguration.getOperationTypes().get(o))
                .flatMap(o -> accountListGbaGateway.getAccountListByPinEqAndActIn(pinEq, o, act, useNewBalance, accountNumbers).stream());
    }

    private void fillBranchInfo(Collection<Account> accounts) {
        log.info("#fillBranchInfo: branchIds {}",
                accounts.stream()
                        .map(Account::getBranchId)
                        .collect(toSet())
        );
        accounts.forEach(account -> account.setBranchInfo(branchInfoService.getBranchInfo(account.getBranchId())));
    }

    private void fillLastTransactionDate(Collection<Account> accounts) {
        long count = Observable.fromIterable(accounts)
                .flatMap(account -> accountingEntryService.getLastTransactionDate(account).map(account::setLastTransactionDate), maxConcurrentRequests)
                .count().blockingGet();

        log.info("#fillLastTransactionDate: found {} dates for {} accounts", count, accounts.size());
    }

    void fillBalanceGovernment(Set<Account> accounts) {
        Set<Account> accountsWithRNO = accounts.stream()
                .filter(account -> CollectionUtils.isNotEmpty(account.getArrests())
                        && account.getArrests().contains(ARREST_RNO)
                        && CURRENCY_CODE_RUR.equals(account.getBaseCurrencyCode()))
                .collect(toSet());
        log.info("#fillBalanceGovernment ruble accounts with H_RNO: {}", accountsWithRNO.size());
        if (CollectionUtils.isNotEmpty(accountsWithRNO)) {
            fillBalance(accountsWithRNO,
                    getSpecialAccountBalance(accountsWithRNO.stream()
                            .map(Account::getAccountNumber)
                            .collect(toSet()), Collections.singleton(BalanceType.BALANCE_GOVERNMENT)),
                    BalanceType.BALANCE_GOVERNMENT);
        }
    }

    private void fillComboInfo(Set<Account> accounts, String pinEq) {
        CardComboAccountResponse response = uwsCardComboAccount10Client.getCardComboAccount(pinEq);
        ComboInfo comboInfo = comboInfoMapper.mapToComboInfo(response);
        log.info("#fillComboInfo: {}", comboInfo);
        accounts.stream()
                .map(account -> account.setIsComboAccount(false).setComboInfo(new ComboInfo()))
                .filter(account -> account.getAccountNumber().equals(response.getEand()) || account.getAccountNumber().equals(response.getEanc()))
                .forEach(account -> account.setIsComboAccount(true).setComboInfo(comboInfo));
    }

    private void fillBalance(Set<Account> accounts, List<AccountBalance> accountBalanceList, BalanceType balanceType) {
        log.info("#fillBalance accountBalanceList size: {}", accountBalanceList.size());
        for (Account account : accounts) {
            Optional<AccountBalance> result = accountBalanceList.stream()
                    .filter(row -> row.getAccountNumber().equals(account.getAccountNumber())
                            && row.getBalanceType() == balanceType)
                    .findAny();
            if (result.isPresent()) {
                account.setBalanceGovernment(result.get().getAmount());
            } else {
                log.error("#fillBalance balance {} for account {} not found!", balanceType, account.getAccountNumber());
            }
