    public CustomerAccountTypes getCustomerAccountTypes(String pinEq, boolean useRestrictions, boolean filterBankruptAccount) {
        CustomerAccountTypes result = customerNewAccountTypesGateway.getCustomerAccountTypes(pinEq);

        log.info("customer {} account types raw = {}",
                pinEq,
                result.getTypes().stream()
                        .map(CustomerAccountTypes.AccountType::getType)
                        .collect(Collectors.toList())
        );

        if (useRestrictions) {
            List<AccountRestrictions> accountRestrictions = customerNewAccountRestrictionsGateway.getAccountRestrictions(pinEq);

            log.info("customer {} account restrictions = {}",
                    pinEq,
                    accountRestrictions.stream()
                            .map(AccountRestrictions::getAccountType)
                            .collect(Collectors.toList())
            );

            if (accountRestrictions.size() != 0) {
                result.getTypes().removeIf(t -> accountRestrictions.stream().noneMatch(ar -> ar.getAccountType().equals(t.getType())));

                for (CustomerAccountTypes.AccountType at : result.getTypes()) {
                    List<AccountRestrictions> accountRestrictionsFiltered = accountRestrictions.stream()
                            .filter(ar -> ar.getAccountType().equals(at.getType()))
                            .collect(Collectors.toList());

                    List<String> currencies = accountRestrictionsFiltered.stream()
                            .flatMap(cc -> cc.getCurrencyCodeList().stream())
                            .collect(Collectors.toList());

                    log.info("customer {} account type {} currency restrictions {}", pinEq, at.getType(), currencies);

                    at.getCurrencies().removeIf(c -> !currencies.contains(c.getCode()));

                    for (CustomerAccountTypes.TypeCurrency tc : at.getCurrencies()) {
                        accountRestrictionsFiltered.stream()
                                .filter(ar -> ar.getCurrencyCodeList().contains(tc.getCode()))
                                .findFirst()
                                .ifPresent(item -> {
                                    tc.setCount(item.getCount());
                                    tc.setReason(item.getReason());
                                });
                    }
                }
            }
        }

        if (filterBankruptAccount) {
            List<CustomerAccountTypes.AccountType> filteredTypes = result.getTypes().stream()
                    .filter(accountType -> !BANKRUPT_ACCOUNT_TYPE_ZO.equals(accountType.getType()))
                    .collect(Collectors.toList());
            result.setTypes(filteredTypes);
        }

        log.info("customer {} account types result = {}",
                pinEq,
                result.getTypes().stream()
                        .map(CustomerAccountTypes.AccountType::getType)
                        .collect(Collectors.toList())
        );

        return result;
    }

